    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // 2. If this is the only bin that can fit the item, prioritize it heavily
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // 3. Dynamic weight based on stream progress. As we approach the end,
    // be more aggressive about filling bins tightly.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (bin_residual as f64 - mean_residual).abs();

    // 4. Heuristic for new bin: only open if the average residual of existing bins
    // is already very low, or if the current item is large and fits poorly elsewhere.
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin unless existing bins are very crowded.
        score += 35.0 - (mean_residual * 0.3);
    }

    // 5. Final adjustment: penalize bins that deviate significantly from the mean residual
    // to encourage bin balancing.
    score += (post_residual as f64 - mean_residual).powi(2) * 0.05;

