pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base penalty for creating a new bin:
    // If bin_residual == bin_capacity, this is the "new bin" candidate.
    // We penalize this unless the open bins are severely fragmented.
    if bin_residual == bin_capacity {
        score += 45.0 + (open_bins_count as f64 * 0.5);
    }

    // 2. Lookahead matching:
    // If the post_residual is close to the next_item_size, it's a high-value placement.
    // We reward placements that leave a residual that can perfectly fit the next item.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score += diff * 0.8;

        // Penalize if the next item cannot fit at all in this specific bin,
        // but only if it's not a new bin.
        if post_residual < next_item_size && bin_residual != bin_capacity {
            score += 15.0;
        }
    }

    // 3. Fragmentation control:
    // Penalize placements that leave a residual smaller than the smallest likely item (e.g., < 10),
    // unless it's a perfect fit (post_residual == 0).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 4. Mean residual alignment:
    // Avoid creating bins that significantly deviate from the global mean residual,
    // as high variance in bin fullness usually indicates poor packing efficiency.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    // 5. Urgency:
    // As the stream progresses, prioritize closing bins (lower score) to tighten packing.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
