        // If this is the last chance for this bin (i.e., it becomes too small for anything),
        // penalize leaving a "dead" gap that is too small for common items (e.g., < 10)
        if post_residual < 10 && post_residual > 0 {
            score += 10.0;
        }

        // Encourage filling bins that are already "fragmented" (low mean_residual)
        if mean_residual < 20.0 {
            score -= 5.0;
        }
    }

