}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize creating small unusable gaps (1-9) which are hard to fill later.
    // We use a non-linear penalty that spikes for small post_residuals.
    let fragmentation_penalty = if post < 10.0 && post > 0.0 {
        (10.0 - post).powi(3) * 5.0
    } else {
        0.0
    };

    // Reward tighter packing (smaller post_residual).
    let tightness_score = post.powf(1.5);

    // Lookahead logic: if next_item_size is large, favor bins that leave enough space for it.
    // If post_residual is smaller than the next item, we penalize the bin.
    let lookahead_penalty = if next_item_size > 0 && post < next_item_size as f64 {
        (next_item_size as f64 - post) * 2.0
    } else {
        0.0
    };

    // Adaptive threshold: as we reach the end of the stream, prioritize closing bins
    // by penalizing the creation of new bins (represented by high bin_residual).
    let new_bin_penalty = if bin_residual == bin_capacity {
        (open_bins_count as f64 * 0.5) + (progress * 50.0)
    } else {
