        let utilization_factor = (bin_capacity as f64 - mean_residual) / bin_capacity as f64;
        score += 150.0 - (utilization_factor * 100.0) + (open_bins_count as f64 * 3.0);

        // Late game: aggressively discourage new bins to finish the stream.
        if progress > 0.85 {
