    if fitting_bins_count < 3 && fitting_bins_count > 0 {
        score -= 40.0 / fitting_bins_count as f64;
    }

    // Global overhead: Penalize the total count of open bins to favor consolidation.
    score += (open_bins_count as f64).powf(1.15) * 1.8;

    score
}

