            score += 20.0;
        }
    }

    // 3. New Bin Thresholding: Prevent opening new bins unless necessary.
    if bin_residual == bin_capacity {
        // Only open a new bin if we have very few options or the mean residual is already quite low.
        if fitting_bins_count > 0 {
            score += 150.0;
        } else {
            score -= 10.0;
        }
    }

    // 4. Global Density Balance: Avoid creating bins with residuals significantly below the current mean.
    if (post_residual as f64) < mean_residual * 0.5 {
        score += 30.0;
    }

    // 5. Progression Weighting: As the stream nears the end, be more aggressive with packing.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

