        if post_residual >= next_item_size {
            let space_efficiency = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
            // Reward bins that leave exactly enough space for the next item plus a small buffer.
            let slack = (post_residual - next_item_size) as f64;
            score -= (450.0 / (1.0 + slack).powf(1.4)) * (1.0 + space_efficiency.sqrt());
        } else {
