            score += (next_item_size as f64).powf(1.25) * 1.2;
        }
    }

    // 3. Density-Aware Consolidation:
    // If the bin is new, decide based on current global density with a steeper threshold.
    if bin_residual == bin_capacity {
        let density_proxy = mean_residual / bin_capacity as f64;
        // If the average bin is empty, opening a new bin is cheap. If full, it's expensive.
        score += if density_proxy < 0.22 { -200.0 } else { 550.0 };
    } else {
        // 4. Fitting Pressure:
        // When few bins fit, add a non-linear penalty for fragmentation to discourage "spreading".
        if fitting_bins_count > 0 && fitting_bins_count < 3 {
            score -= 600.0 / (fitting_bins_count as f64).powf(0.5);
        }
    }

    // 5. Temporal Decay:
    // As the stream approaches the end, increase the cost of leaving any bin half-empty.
    let progress = step_index as f64 / total_items as f64;
    score += (post_residual as f64) * (progress * 3.5);

    // 6. Global Fragmentation Control:
    // Penalize the creation of "orphan" bins based on the square root of open_bins_count to keep count low.
    score += (open_bins_count as f64).powf(1.15) * 4.0;

    // 7. Small Item Optimization:
    // For small items, actively push them into the most "occupied" bins to maximize residual space in others.
    if item_size <= (bin_capacity / 5) {
