    score += (open_bins_count as f64).ln() * 45.0;

    // 7. Small Item Optimization:
    // Force small items into the most packed bins (lowest post_residual) to maintain 
    // empty space in bins with higher capacity for upcoming large items.
    if item_size < (bin_capacity / 5) {
