}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // ARCHETYPE: Aggressive 2-step lookahead matching
    // Objective: Minimize post_residual, but heavily penalize creating small "dead" gaps (e.g., 1-9)
    // unless the next item is likely to fit there, or we are nearing the end of the stream.

    let mut score = post_residual as f64;

    // 1. Dead-space penalty: If post_residual is small but > 0, it's usually bad.
    // We penalize gaps in the [1, 9] range as they are hard to fill.
    if post_residual > 0 && post_residual < 10 {
