    // 2. Lookahead synergy: If the next item fits perfectly into the post_residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = (post_residual - next_item_size) as f64;
        // If it fits exactly, give a massive bonus.
