    // 3. Global Bin Management:
    // If this is a new bin (bin_residual == bin_capacity), penalize opening it unless
    // we have no other choice or the current average residual is very high.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Discourage opening new bins if alternatives exist.
            score += 60.0;
