        let progress = step_index as f64 / total_items as f64;
        score += progress * 20.0;
    }

    // 4. Mean Residual Balancing:
    // If this bin's post_residual is significantly better than the global mean, reward it.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // 5. Last-chance logic: If this is the only bin that fits, prioritize it over opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
