            let fit_efficiency = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
            // Reward exact fit potential with higher magnitude
            score -= (450.0 / (1.0 + (post_residual - next_item_size) as f64).powf(1.4)) * (1.0 + fit_efficiency);
        } else {
            // Stronger penalty for bins that cannot fit the next item if it's significant
            score += (next_item_size as f64).powf(1.25) * 1.2;
        }
    }

    // 3. Density-Aware Consolidation:
    // If we have few fitting bins, force the tightest one; avoid spreading items too thin.
    if fitting_bins_count > 0 && fitting_bins_count <= 6 {
        score -= (650.0 / fitting_bins_count as f64);
    }

    // 4. New Bin Candidate Logic:
    // Dynamically adjust the cost of opening a new bin based on current packing density.
    if bin_residual == bin_capacity {
        let density_proxy = mean_residual / bin_capacity as f64;
        // If average waste is high, opening a new bin is a failure; penalize higher.
        if density_proxy < 0.15 {
            score -= 220.0; 
        } else {
            score += 650.0; 
        }
    }

    // 5. Temporal Pressure:
    // As the stream progresses, prioritize closing gaps in existing bins to avoid orphans.
    let progress = step_index as f64 / total_items as f64;
    score += (post_residual as f64) * (progress * 4.5);

    // 6. Global Fragmentation Control:
    // Penalize the creation of "orphan" bins based on current open_bins_count.
    // This acts as a soft constraint on the total bin count.
    score += (open_bins_count as f64).powf(1.4) * 8.0;

    // 7. Small Item Optimization:
    // Direct small items into the most crowded bin to preserve space for larger items.
    if item_size < (bin_capacity / 5) {
        score += (bin_residual as f64) * 0.45;
    }

    // 8. Residual Balancing:
    // Penalize extreme residual variance by discouraging bins that are too empty.
    if post_residual > (bin_capacity / 2) {
        score += (post_residual as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: heavily favor bins where post_residual is small (tight fit)
    // We penalize larger post_residuals to discourage fragmentation.
    score += (post_residual as f64) * 1.5;

    // 2. Lookahead Synergy: If the next item fits perfectly into the remaining space,
    // reduce the score significantly to prioritize this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let waste_after_next = (post_residual - next_item_size) as f64;
        score -= (100.0 - waste_after_next) * 0.8;
    }

    // 3. Avoiding "New Bin" trap:
    // If this is a new bin (bin_residual == bin_capacity), add a penalty unless it's 
    // the only option or the current fit is terrible (e.g., mean_residual is very low).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Penalize opening a new bin if other options exist
            score += 45.0 + (mean_residual * 0.5);
        }
    } else {
        // 4. Mean Residual Balancing:
        // If this bin's post_residual is much larger than the global mean, 
        // it creates a "dead space" outlier. Penalize based on deviation.
        if (post_residual as f64) > mean_residual {
            score += (post_residual as f64 - mean_residual) * 0.4;
        }
    }

    // 5. Progression adjustment:
    // As we approach the end of the stream, prioritize closing existing bins (lower score)
    // over opening new ones by tightening the threshold.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(
