            score += (next_item_size as f64).powf(1.25);
        }
    }

    // 3. Forced Selection: Bias towards filling existing bins to minimize open_bins_count
    if fitting_bins_count > 0 {
        score -= (650.0 / (fitting_bins_count as f64).sqrt());
    }

    // 4. New Bin Candidate Logic: Dynamic threshold based on total stream progress
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        // As stream progresses, the penalty for opening a new bin increases (avoid fragmentation)
        let new_bin_barrier = 350.0 + (progress * 400.0);
        let density_proxy = mean_residual / bin_capacity as f64;

        if density_proxy < 0.15 {
            score -= 100.0; // Allow new bins early if density is very low
        } else {
            score += new_bin_barrier;
        }
    }

    // 5. Residual Variance Control: Penalize bins that create "unfillable" gaps
    // If post_residual is small but not zero, it's often a "dead" gap.
    if post_residual > 0 && post_residual < 8 {
        score += 150.0;
    }

    // 6. Global Fragmentation Control:
    // Increased penalty for the number of open bins to force consolidation
    score += (open_bins_count as f64).powf(1.4) * 8.0;

    // 7. Adaptive Small Item Placement:
    // If item is small, prioritize bins that are already nearly full (minimizing footprint)
    if item_size <= (bin_capacity / 5) {
        score += (bin_capacity - bin_residual) as f64 * 0.5;
    }

    // 8. End-of-stream cleanup: tighten constraints as capacity reaches exhaustion
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score += (post_residual as f64) * 10.0;
    }

    score
}

pub fn score_bin(
