) -> f64 {
    // Base score: prioritize tighter fits exponentially to maximize density.
    let mut score = (post_residual as f64).powf(1.8);

    // Penalty for creating "dead zones" (unusable space < 10 units).
    if post_residual > 0 && post_residual < 10 {
        score += 85.0 + (10.0 - post_residual as f64) * 8.0;
    }

    // Lookahead: If the next item is large, favor bins that can accommodate it.
    // If the current placement makes the next item impossible to fit, penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that leave exactly enough space for the next item (synergy).
            score -= 150.0 / (1.0 + (post_residual - next_item_size) as f64).sqrt();
        } else if next_item_size > 60 {
            score += 120.0;
        }
    }

    // Dynamic New Bin Logic:
    // If bin_residual == bin_capacity, we are considering a new bin.
    if bin_residual == bin_capacity {
        // High barrier to opening a new bin unless there are very few options or the stream is nearly over.
        let progress = step_index as f64 / total_items as f64;
        let base_new_bin_cost = 550.0;
        // As we reach the end, opening a new bin is very costly to force consolidation.
        score += base_new_bin_cost + (progress * 400.0);

        // If we have many open bins, heavily discourage opening more.
        score += (open_bins_count as f64) * 15.0;
    } else {
        // For existing bins, reward those that align with the current mean to keep distribution uniform.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.4;
    }

    // Scarcity adjustment: if very few bins can fit this item, prioritize existing bins over new ones.
    if fitting_bins_count > 0 && fitting_bins_count < 3 {
        score -= 200.0;
    }

    // Small item packing: If item is small, prefer bins that are already quite full (low residual).
    if item_size < 20 {
        score += (bin_residual as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
