        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 25.0;
        }

        // Penalty for creating 'dead space' that is too small for common items.
        // If post_residual is < 10, it's often unusable.
        if post_residual < 10 && post_residual > 0 {
            score += 15.0;
        }

        // Global state awareness: If this bin's residual is significantly better 
        // than the average residual, prioritize keeping it tight.
        if (post_residual as f64) < mean_residual {
