    let progress = step_index as f64 / total_items as f64;
    score += (open_bins_count as f64) * (2.0 + progress * 5.0);

    // New Bin Candidate Logic:
    // Only open a new bin if the current mean_residual suggests we are under-utilizing existing ones.
    if bin_residual == bin_capacity {
        if mean_residual < (bin_capacity as f64 * 0.35) {
            // If average empty space is high, opening a new bin is less harmful
            score += 110.0;
        } else {
            // Otherwise, strongly discourage opening a new bin
            score += 550.0;
        }
    }

    // Small item optimization:
