        if avg_fill < 0.75 {
            score += 300.0; // High resistance to new bins
        } else {
            score -= 50.0;  // Open new bin if existing bins are already quite full
        }
        score += (open_bins_count as f64) * 2.5;
    }

    // Small item optimization: If the item is small, place it in the most crowded bin
