    // If post_residual is < 10, it creates a "dead zone" that cannot fit any items.
    // We penalize this heavily.

    let mut score = post_residual as f64;

    // 1. Dead space penalty: If we leave a gap smaller than the minimum possible item (10),
    // it's highly likely to remain empty.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead optimization: If the next item could have fit better in the current bin
    // than the current item, penalize the choice.
    if next_item_size > 0 && next_item_size <= post_residual {
        // If the current placement forces the next item into a new bin, penalize.
        score += 15.0;
    }

    // 3. Open bins pressure: As we reach the end of the stream, prioritize closing bins.
    let progress = step_index as f64 / total_items as f64;
    score += (open_bins_count as f64) * (1.0 + progress * 2.0);

    // 4. New bin management: If this is an empty bin (bin_residual == bin_capacity),
    // only choose it if the penalty for fitting into existing bins is extreme.
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin is high, but decreases as fitting_bins_count
        // suggests we are running out of options or the current options are all "bad" (high score).
        score = 60.0 + (open_bins_count as f64 * 0.5);
    } else {
        // Favor bins that result in a residual close to the mean, maintaining balance.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;
    let cap = bin_capacity as f64;

    // Mutation: Refined residual penalty with a dynamic shift to minimize micro-gaps.
    // The exponent 1.95 better balances small residuals and large wasted spaces.
    let mut score = post_res + (post_res.powf(1.95) * 0.82);

    // Adaptive Fragmentation: Target residual space relative to the mean_residual.
    let avg_item_est = (cap - mean_residual).max(1.0);
    if post_res > 0.0 && post_res < avg_item_est {
        score += (avg_item_est - post_res).powf(2.35) * 2.85;
    }

    // Lookahead Synergy: Enhanced reward for tight fits that allow subsequent items.
    if next_item_size > 0 {
        let next_f = next_item_size as f64;
        if post_residual >= next_item_size {
            let remainder = post_res - next_f;
            // Reward exact fit with higher priority to keep bins "active" and productive.
            score -= (next_f * 2.30) + (4.2 / (remainder + 0.01).powf(1.95));
        } else {
            // Penalize blocking the next item; escalating penalty to force consolidation.
            score += next_f * (3.8 + (progress * 4.2));
        }
    }

    // Bin Creation Logic:
    if bin_residual == bin_capacity {
        // Tighter control on new bin proliferation using a non-linear clutter factor.
        let base_cost = 74.0;
        let progress_penalty = (1.0 - progress.powf(0.88)) * 155.0;
        let clutter_factor = (open_bins_count as f64).powf(1.55) * 9.5;
        score = base_cost + progress_penalty + clutter_factor;
    } else {
        // Utilization Reward: Aggressive incentive for high bin occupancy.
        let utilization = 1.0 - (post_res / cap);
        score -= utilization * 105.0;

        // "Must-use" logic: Strong preference for the only bin that can house the item.
        if fitting_bins_count == 1 {
            score -= 220.0;
        }

        // Anti-sparsity: Penalize low-occupancy bins to force packing into fewer bins.
        if utilization < 0.35 {
            score += (open_bins_count as f64).powf(1.35) * 6.5;
        }
    }

    // Late-stage compaction: Shift to aggressive consolidation at 85% progress.
    let entropy_weight = if progress > 0.85 { 0.008 } else { 5.5 };
    score += (open_bins_count as f64).ln() * entropy_weight;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

