    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2. Aggressive lookahead: reward bins where the post_residual can accommodate the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Strong reward for a "perfect" match or near-perfect match for the next item.
            score -= 15.0 * (1.0 - (post_residual - next_item_size) as f64 / 100.0);
        } else {
            // Penalize leaving space that is too small for the next item.
            score += 5.0;
        }
    }

    // 3. Dynamic balance: Prefer bins closer to the mean residual to keep packing density uniform.
    let dev_from_mean = (post_residual as f64 - mean_residual).abs();
    score += dev_from_mean * 0.1;

    // 4. Strategic new bin logic:
    // If this is a new bin (bin_residual == bin_capacity), penalize it heavily unless 
    // no other bin can fit the item or the current fits are extremely poor.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 45.0; // High barrier to opening a new bin
        } else {
            score -= 10.0; // Necessary evil: open new bin
        }
    }

    // 5. Last chance protection: If this is the only bin that can fit the item, prioritize it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 6. Progress weighting: In late stages, prioritize filling existing bins to reduce tail waste.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (open_bins_count as f64 * 0.5);

    score
}

