    if !is_new_bin && fitting_bins_count == 1 {
        score -= 20.0;
    }

    // 5. Global Load Balancing
    // Penalize bins that deviate too far from the mean residual to keep bin fill levels uniform.
    let deviation = (post_residual as f64 - mean_residual).abs();
