    let post_res = post_residual as f64;
    let cap = bin_capacity as f64;
    let res = bin_residual as f64;

    // Core score: Penalize post-residual with a tighter focus on avoiding small, unusable gaps.
    let mut score = post_res + (post_res.powf(1.92) * 0.95);

    // Dynamic Fragmentation: Refine the threshold for "dead zones".
    // Use the ratio of bin_residual to capacity to identify bins that are becoming stagnant.
    let avg_item_est = (cap - mean_residual).max(1.0);
    if post_res > 0.0 && post_res < avg_item_est {
        score += (avg_item_est - post_res).powf(2.35) * 3.2;
    }

    // Lookahead Synergy: Improved heuristic for next_item_size.
    if next_item_size > 0 {
        let next_f = next_item_size as f64;
        if post_residual >= next_item_size {
            // Reward bins that maintain enough space for the next item, specifically targeting tight fits.
            let slack = post_res - next_f;
            score -= (next_f * 2.25) + (4.2 / (slack + 0.02).powf(1.95));
        } else {
            // Penalize blocking the next item; scale penalty by progress to force consolidation.
            score += next_f * (3.8 + (progress * 4.2));
        }
    }

    // Bin Creation Logic:
    if bin_residual == bin_capacity {
        // Higher base_cost and tighter clutter penalty to prevent unnecessary bin proliferation.
        // Penalty scales with open_bins_count to favor existing bins over new ones.
        let base_cost = 75.0;
        let progress_penalty = (1.0 - progress.powf(0.85)) * 155.0;
        let clutter_factor = (open_bins_count as f64).powf(1.52) * 9.5;
        score = base_cost + progress_penalty + clutter_factor;
    } else {
        // Utilization Reward: Strongly incentivize filling existing capacity.
        let utilization = 1.0 - (post_res / cap);
        score -= utilization * 105.0;

        // "Must-use" logic: Aggressively target the last available fitting bin.
        if fitting_bins_count == 1 {
            score -= 210.0;
        }

        // Anti-sparsity: Penalize bins that remain under-utilized.
        // Sensitivity increased to force consolidation of low-utilization bins.
        if utilization < 0.45 {
            score += (open_bins_count as f64).powf(1.35) * 6.8;
        }

        // Residual-to-Capacity ratio penalty to discourage 'fragmentation' of empty space.
        score += (res / cap) * 15.0;
    }

    // Late-stage compaction: Aggressive consolidation in the final 20% of the stream.
    let entropy_weight = if progress > 0.80 { 0.012 } else { 5.2 };
    score += (open_bins_count as f64).ln() * entropy_weight;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
