    // Global state awareness: encourage filling bins that are already below the mean_residual
    // to keep the distribution of remaining spaces consistent.
    if (bin_residual as f64) > mean_residual {
        score += 5.0 * (1.0 - progress);
    }

    // Criticality check: if this is the last bin that can fit the item, 
    // prioritize it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    score
}

