    let post_res = post_residual as f64;
    let cap = bin_capacity as f64;

    // Refined core score: Penalize post-residual with optimized non-linear growth to avoid micro-gaps.
    let mut score = post_res + (post_res.powf(1.88) * 0.90);

    // Adaptive Fragmentation: Use a tightened dynamic threshold based on mean residual.
    let avg_item_est = (cap - mean_residual).max(1.0);
    if post_res > 0.0 && post_res < avg_item_est {
        score += (avg_item_est - post_res).powf(2.18) * 2.4;
    }

    // Lookahead Synergy: Improved reward for accommodating the next item in the stream.
    if next_item_size > 0 {
        let next_f = next_item_size as f64;
        if post_residual >= next_item_size {
            let remainder = post_res - next_f;
            // Reward perfect fit or small remainders that don't strand the bin.
            score -= (next_f * 2.10) + (4.0 / (remainder + 0.012).powf(1.9));
        } else {
            // Penalize blocking the next item; scale penalty by progress to force efficiency early.
            score += next_f * (3.5 + (progress * 3.8));
        }
    }

    // Bin Creation Logic:
    if bin_residual == bin_capacity {
        // Tightened base_cost and increased clutter penalty to reduce bin proliferation.
        let base_cost = 68.0;
        let progress_penalty = (1.0 - progress.powf(0.88)) * 145.0;
        let clutter_factor = (open_bins_count as f64).powf(1.50) * 9.5;
        score = base_cost + progress_penalty + clutter_factor;
    } else {
        // Utilization Reward: Strongly incentivize filling existing capacity.
        let utilization = 1.0 - (post_res / cap);
        score -= utilization * 95.0;

        // "Must-use" logic: Aggressively target the last available fitting bin.
        if fitting_bins_count == 1 {
            score -= 200.0;
        }

        // Anti-sparsity: Penalize bins that remain under-utilized.
        if utilization < 0.45 {
            score += (open_bins_count as f64).powf(1.35) * 6.0;
        }
    }

    // Late-stage compaction: Aggressive consolidation in the final 20% of the stream.
    // Reduced entropy weight to prevent excessive fragmentation during final stages.
    let entropy_weight = if progress > 0.80 { 0.012 } else { 5.0 };
    score += (open_bins_count as f64).ln() * entropy_weight;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large post_residuals (dead space)
    score += post_residual as f64 * 0.5;

    // 2. Harmonic Class Penalty: If we leave a gap that is too small for most items (e.g., < 10),
    // we penalize it heavily unless it's a perfect fit (post_residual == 0).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 3. Next-Item Lookahead: If the next item can fit in the post_residual space, 
    // reward this bin heavily to keep the bin packing tight.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (100.0 - post_residual as f64) * 0.8;
    }

    // 4. New Bin Thresholding: If this is an empty bin (new bin candidate)
    if bin_residual == bin_capacity {
        // Only open a new bin if the current open bins are becoming very fragmented
        // or if we have very few open bins relative to the item stream.
        if fitting_bins_count > 0 {
            score += 45.0;
        } else {
            score -= 10.0;
        }
    }

    // 5. Fragmentation Control: If mean_residual is low, we are in a tight packing phase.
    // Penalize bins that deviate significantly from the mean_residual.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    // 6. Final scaling for stream progression: As we approach the end of the stream,
    // be more aggressive in filling existing bins to avoid leftover items in new bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

