    let post_res = post_residual as f64;
    let cap = bin_capacity as f64;

    // Refined Penalty for residual space: Focus on minimizing 'dead' space that cannot fit typical items.
    // Increased exponent to punish mid-range gaps more aggressively.
    let mut score = post_res + (post_res.powf(2.12) * 0.88);

    // Adaptive Fragmentation: Target the specific mean residual gap to maximize bin density.
    let avg_item_est = (cap - mean_residual).clamp(1.0, cap * 0.75);
    if post_res > 0.0 && post_res < avg_item_est {
        score += (avg_item_est - post_res).powf(2.45) * 3.2;
    }

    // Lookahead Synergy: Dynamic weighting for next_item_size.
    if next_item_size > 0 {
        let next_f = next_item_size as f64;
        if post_residual >= next_item_size {
            // Reward filling bins that can accommodate the next item; incentivize tight fits.
            let slack = post_res - next_f;
            score -= (next_f * 2.45) + (4.2 / (slack + 0.012).powf(1.95));
        } else {
            // Penalize blocking the next item; increasing penalty as stream progresses.
            score += next_f * (4.2 + (progress * 5.8));
        }
    }

    // Bin Creation Logic:
    if bin_residual == bin_capacity {
        // Higher base cost and non-linear scaling of open_bins_count to prevent excessive proliferation.
        let base_cost = 82.0;
        let progress_penalty = (1.0 - progress.powf(0.85)) * 160.0;
        let clutter_factor = (open_bins_count as f64).powf(1.55) * 9.6;
        score = base_cost + progress_penalty + clutter_factor;
    } else {
        // Utilization Reward: Strongly incentivize filling existing capacity.
        let utilization = 1.0 - (post_res / cap);
        score -= utilization * 105.0;

        // Consolidate space: Prioritize bins with minimal remaining capacity to reduce fragmentation.
        if fitting_bins_count == 1 {
            score -= 240.0;
        } else if fitting_bins_count < 4 {
            score -= 60.0 * (1.0 - progress);
        }

        // Anti-sparsity: Penalize bins that remain under-utilized.
        if utilization < 0.38 {
            score += (open_bins_count as f64).powf(1.40) * 6.8;
        }
    }

    // Late-stage compaction: Aggressive consolidation in the final 15% of the stream.
    let entropy_weight = if progress > 0.85 { 0.008 } else { 5.2 };
    score += (open_bins_count as f64).ln() * entropy_weight;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Penalize large remaining space to keep bins tightly packed.
    // If post_residual is large, score is higher (worse).
    score += post_residual as f64 * 1.5;

    // 2. Lookahead Integration: If next item is large, avoid leaving a small gap.
    // If next_item_size > post_residual, we penalize this bin because it creates a "fragmented" space.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 2.5;
        } else {
            // Reward bins that can accommodate the next item perfectly
            score -= (bin_capacity - post_residual) as f64 * 0.2;
        }
    }

    // 3. New Bin Thresholding:
    // If this is a new bin (bin_residual == bin_capacity), penalize opening it based on current fill density.
    if bin_residual == bin_capacity {
        // Only open new bins if the average residual is already quite low (bins are full).
        // If mean_residual is high, we have room elsewhere, so penalize opening a new bin.
        score += mean_residual * 5.0;
        // As we reach the end of the stream, discourage opening new bins.
        score += (1.0 - progress) * 20.0;
    } else {
        // 4. Fitting Bin Bias: 
        // If this is the ONLY bin that fits the item, make it very attractive.
        if fitting_bins_count == 1 {
            score -= 50.0;
        }

        // Encourage using bins that are already closer to the mean residual to maintain uniformity.
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += deviation * 0.5;
    }

    score
}

