    let post_res = post_residual as f64;
    let cap = bin_capacity as f64;

    // Refined core score: Non-linear penalty for fragmentation, adjusted for sharper sensitivity to small gaps.
    let mut score = post_res + (post_res.powf(1.95) * 1.12);

    // Adaptive Fragmentation: Threshold-based suppression of 'dead' space.
    let avg_item_est = (cap - mean_residual).max(1.0);
    if post_res > 0.0 && post_res < avg_item_est {
        score += (avg_item_est - post_res).powf(2.35) * 2.85;
    }

    // Lookahead Synergy: Optimized weights for next_item_size fitting.
    if next_item_size > 0 {
        let next_f = next_item_size as f64;
        if post_residual >= next_item_size {
            let remainder = post_res - next_f;
            // Reward perfect fit more heavily; penalize leaving a 'sliver' that cannot hold another item.
            score -= (next_f * 2.25) + (4.2 / (remainder + 0.012).powf(1.92));
        } else {
            // Escalating penalty for blocking the next item based on current bin density.
            score += next_f * (3.8 + (progress * 4.2));
        }
    }

    if bin_residual == bin_capacity {
        // Bin Creation Logic: Stricter control on proliferation.
        let base_cost = 78.0;
        let progress_penalty = (1.0 - progress.powf(0.85)) * 155.0;
        let clutter_factor = (open_bins_count as f64).powf(1.52) * 9.6;
        score = base_cost + progress_penalty + clutter_factor;
    } else {
        // Utilization Reward: Strengthened to encourage packing density.
        let utilization = 1.0 - (post_res / cap);
        score -= utilization * 105.0;

        // "Must-use" logic: Aggressive consolidation for single-fit scenarios.
        if fitting_bins_count == 1 {
            score -= 215.0;
        }

        // Anti-sparsity: Penalize under-utilized bins more aggressively as bin count grows.
        if utilization < 0.45 {
            score += (open_bins_count as f64).powf(1.35) * 6.4;
        }
    }

    // Late-stage compaction: Shift to extreme consolidation in the final 15% of the stream.
    // Reduced entropy weight to allow the heuristic to lock into fewer bins.
    let entropy_weight = if progress > 0.85 { 0.008 } else { 5.2 };
    score += (open_bins_count as f64).ln() * entropy_weight;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals to encourage tight packing.
    // We add a weight to the post_residual itself.
    score += post_residual as f64 * 1.5;

    // 2. Lookahead Synergy: If the next item fits perfectly into the remaining space,
    // give a massive reward (negative score) to this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = (post_residual - next_item_size) as f64;
        // Reward is inversely proportional to the wasted space after placing the next item.
        score -= (100.0 - diff) * 2.0;
    }

    // 3. New Bin Management: If this is an empty bin, penalize it based on how many
    // open bins are already available to discourage fragmentation.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 15.0;
        // If we have many fitting bins, opening a new one is very undesirable.
        score += (fitting_bins_count as f64) * 20.0;
    }

    // 4. Global Balance: If the current bin is significantly "emptier" than the mean
    // of all open bins, penalize it to force consolidation.
    if (bin_residual as f64) > mean_residual {
        score += (bin_residual as f64 - mean_residual) * 0.8;
    }

    // 5. Last Chance Heuristic: If this is the only bin that can fit the current item,
    // force its selection by lowering the score significantly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 6. Progress Scaling: As we reach the end of the stream, prioritize closing
    // existing bins over starting new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 40.0;
    }

    score
}

