    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Minimize post_residual to keep bins tight.
    // We already start with post_residual as the base score.

    // 2. Lookahead Integration: If the next item fits into the current post_residual, 
    // prioritize this bin to maximize packing density.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 * (1.0 - progress);
    }

    // 3. Fragmentation Penalty: If post_residual is small but > 0, it creates "dead space".
    // Heavily penalize tiny gaps that are unlikely to fit future items (e.g., < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // 4. Global Load Balancing: If we are late in the stream, avoid opening new bins 
    // unless absolutely necessary.
    if bin_residual == bin_capacity {
        if progress < 0.8 {
            // Early game: Allow new bins to keep future options open.
            score += 15.0;
        } else {
            // Late game: Heavily penalize opening new bins.
            score += 100.0;
        }
    }

    // 5. Fitting Constraint: If this is the only bin that can fit the item, 
    // prioritize it to avoid mandatory new bin creation.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // 6. Mean Residual Correction: Favor bins that stay close to the current average
    // to keep the packing uniform across all active bins.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;
    let cap = bin_capacity as f64;

    // Core score: Penalize post-residual with aggressive non-linear growth to eliminate micro-gaps.
    // Tightened exponent to force closer fits.
    let mut score = post_res + (post_res.powf(2.05) * 0.88);

    // Adaptive Fragmentation: Use a tighter threshold for 'useless' gaps.
    let avg_item_est = (cap - mean_residual).max(1.0);
    if post_res > 0.0 && post_res < avg_item_est {
        score += (avg_item_est - post_res).powf(2.45) * 3.2;
    }

    // Lookahead Synergy: Fine-tune the reward for accommodating the next item.
    if next_item_size > 0 {
        let next_f = next_item_size as f64;
        if post_residual >= next_item_size {
            let remainder = post_res - next_f;
            // Reward perfect fit or small remainders.
            score -= (next_f * 2.15) + (4.2 / (remainder + 0.01).powf(1.95));
        } else {
            // Penalize blocking the next item; aggressive early-game scaling.
            score += next_f * (3.8 + (progress * 4.2));
        }
    }

    // Bin Creation Logic:
    if bin_residual == bin_capacity {
        // Dynamic cost to prevent proliferation, scaled by the current item's difficulty.
        let base_cost = 75.0;
        let progress_penalty = (1.0 - progress.powf(0.85)) * 155.0;
        let clutter_factor = (open_bins_count as f64).powf(1.52) * 9.2;
        score = base_cost + progress_penalty + clutter_factor;
    } else {
        // Utilization Reward: Incentivize filling existing capacity.
        let utilization = 1.0 - (post_res / cap);
        score -= utilization * 105.0;

        // "Must-use" logic: Aggressively target the last available fitting bin.
        if fitting_bins_count == 1 {
            score -= 215.0;
        }

        // Anti-sparsity: Penalize bins that remain under-utilized.
        // Increased threshold to 0.48 to force tighter packing.
        if utilization < 0.48 {
            score += (open_bins_count as f64).powf(1.35) * 6.5;
        }
    }

    // Late-stage compaction: Aggressive consolidation in the final 15% of the stream.
    let entropy_weight = if progress > 0.85 { 0.008 } else { 5.2 };
    score += (open_bins_count as f64).ln() * entropy_weight;

    // Residual Variance dampener: Penalize bins that create large deviations from mean_residual.
    score += (post_res - mean_residual).abs().powf(1.1) * 0.5;

    score
}

