    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals (dead space)
    // 2. Harmonic Class Logic: Favor residuals that can accommodate common item sizes (e.g., 20, 25, 33, 50)
    let remainder_penalty = (post_residual % 25) as f64 * 0.5;
    score += remainder_penalty;

    // 3. Lookahead Integration: If next_item_size fits in the new post_residual, drastically lower the score
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 1.2;
    }

    // 4. New Bin Thresholding: Prevent premature opening of new bins unless existing fit is terrible
    if bin_residual == bin_capacity {
        // High barrier to opening a new bin: base cost is high
        score = 45.0;
        // If we have many open bins, make it even harder to open a new one
        score += (open_bins_count as f64) * 2.0;
        // If the current item is very large, it's better to open a new bin than crowd a tight bin
        if item_size > 70 {
            score -= 20.0;
        }
    } else {
        // Favor bins where the new residual is close to the mean residual of other bins (load balancing)
        let balance_factor = (post_residual as f64 - mean_residual).abs() * 0.1;
        score += balance_factor;
    }

    // 5. Urgency: If this is the only bin that fits the item, prioritize it heavily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;
    let cap = bin_capacity as f64;

    // Core score: Penalize post-residual with a sharper cliff to discourage "near-empty" bin states.
    let mut score = post_res + (post_res.powf(2.05) * 0.88);

    // Adaptive Fragmentation: Refined thresholding. 
    // Using a coefficient of 0.85 of mean_residual as the "danger zone" for mid-sized item stranding.
    let avg_item_est = (cap - mean_residual).max(1.0);
    if post_res > 0.0 && post_res < avg_item_est {
        score += (avg_item_est - post_res).powf(2.15) * 2.75;
    }

    // Lookahead Synergy: Strengthened lookahead weight.
    if next_item_size > 0 {
        let next_f = next_item_size as f64;
        if post_residual >= next_item_size {
            let remainder = post_res - next_f;
            // Reward perfect fit or high-density packing, with a tighter penalty for "wasted" remainders.
            score -= (next_f * 2.25) + (4.2 / (remainder + 0.012).powf(1.95));
        } else {
            // Penalize blocking the next item; aggressive scaling to prioritize packing current bin capacity.
            score += next_f * (3.8 + (progress * 4.2));
        }
    }

    // Bin Creation Logic:
    if bin_residual == bin_capacity {
        // Dynamic barrier: Increase cost to open new bins as total items processed increases, 
        // effectively forcing higher density in existing bins.
        let base_cost = 72.0;
        let progress_penalty = (1.0 - progress.powf(0.85)) * 155.0;
        let clutter_factor = (open_bins_count as f64).powf(1.52) * 9.2;
        score = base_cost + progress_penalty + clutter_factor;
    } else {
        // Utilization Reward: Non-linear reward for high utilization.
        let utilization = 1.0 - (post_res / cap);
        score -= utilization.powf(1.15) * 115.0;

        // Consolidation: Strong incentive to finish off bins that are near capacity.
        if fitting_bins_count == 1 {
            score -= 210.0;
        }

        // Anti-sparsity: Penalize under-utilized bins, adjusted for open_bins_count to prevent excessive spreading.
        if utilization < 0.45 {
            score += (open_bins_count as f64).powf(1.35) * 6.5;
        }
    }

    // Late-stage compaction: Aggressive consolidation in the final 15% of the stream.
    // Discouraging the creation of new bins when we are near the end.
    let entropy_weight = if progress > 0.85 { 0.008 } else { 5.2 };
    score += (open_bins_count as f64).ln() * entropy_weight;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Strategy: Strict Best-Fit with aggressive penalty for fragmentation (dead space < 10).
    // Penalize opening new bins unless the current bin fit is extremely suboptimal.

    let mut score = post_residual as f64;

    // 1. Fragmentation Penalty: If post_residual is small (1..9), it's likely dead space.
    // Penalize heavily to push items into bins that leave larger, more usable residuals.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0 - (post_residual as f64 * 4.0);
    }

    // 2. Lookahead Synergy: If next_item_size fits in the remaining space, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
    }

    // 3. New Bin Penalty: Discourage opening a new bin unless the current options are all poor.
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty based on open_bins_count.
    if bin_residual == bin_capacity {
        score += 20.0 + (open_bins_count as f64 * 2.5);
    }

    // 4. Fitting Pressure: If this is the last bin that can fit the item, prioritize it to avoid new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 5. Global Efficiency: If the current bin is significantly worse than the mean, penalize it.
    if (bin_residual as f64) > (mean_residual * 1.5) {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;
    let cap = bin_capacity as f64;

    // Mutation: Increase penalty for gaps to force tighter packing.
    // Shifted exponent to 2.25 and scaling to 0.82 to penalize larger gaps more aggressively.
    let mut score = post_res + (post_res.powf(2.25) * 0.82);

    // Adaptive Fragmentation: Thresholding against mean_residual to avoid creating small, unfillable holes.
    let avg_item_est = (cap - mean_residual).max(1.0);
    if post_res > 0.0 && post_res < avg_item_est {
        score += (avg_item_est - post_res).powf(2.6) * 3.8;
    }

    // Lookahead Synergy: Improved reward for accommodating the next item.
    if next_item_size > 0 {
        let next_f = next_item_size as f64;
        if post_residual >= next_item_size {
            let remainder = post_res - next_f;
            // Reward exact fit (remainder 0) with a sharper exponential decay.
            score -= (next_f * 2.85) + (7.5 / (remainder + 0.01).powf(2.4));
        } else {
            // Penalize blocking the next item significantly more in early stages.
            score += next_f * (5.2 + (progress * 7.5));
        }
    }

    // Bin Creation Logic:
    if bin_residual == bin_capacity {
        // Higher base_cost and tighter clutter penalty to prevent bin proliferation.
        // Adjusted progress penalty to be more lenient early, more restrictive late.
        let base_cost = 82.0;
        let progress_penalty = (1.0 - progress.powf(0.95)) * 190.0;
        let clutter_factor = (open_bins_count as f64).powf(1.75) * 14.0;
        score = base_cost + progress_penalty + clutter_factor;
    } else {
        // Utilization Reward: Favor filling existing capacity over new bins.
        let utilization = 1.0 - (post_res / cap);
        score -= utilization * 150.0;

        // Consolidate space: Favor bins that are the only viable option for an item.
        if fitting_bins_count == 1 {
            score -= 320.0;
        }

        // Anti-sparsity: Stronger penalization for under-utilized bins to prevent fragmentation.
        if utilization < 0.50 {
            score += (open_bins_count as f64).powf(1.60) * 11.0;
        }
    }

    // Late-stage compaction: Aggressive consolidation in the final 15% of the stream.
    let entropy_weight = if progress > 0.85 { 0.005 } else { 8.5 };
    score += (open_bins_count as f64).ln() * entropy_weight;

    score
}
